const LF = String.fromCharCode(10);
const v = $input.first().json;
let verdict = 'QUIET';
let summary = 'No new qualifying Dark Reading articles in the last 24 hours';
const lines = [];
if (v.status === 'quiet') {
  lines.push('Quiet day: no qualifying Dark Reading articles were found in the previous 24 hours.');
  lines.push('The feed was retrieved and validated successfully (' + v.feedItemCount + ' item(s) in feed).');
  if (v.alreadySentCount > 0) lines.push(v.alreadySentCount + ' recent article(s) were already reported earlier.');
  if (v.undatedCount > 0) lines.push('Data quality: ' + v.undatedCount + ' item(s) skipped due to missing or invalid publication dates, so this result may be incomplete.');
} else if (v.status === 'dataquality') {
  verdict = 'ERROR';
  summary = 'Feed readable but publication dates missing or invalid';
  lines.push('The Dark Reading feed was retrieved, but none of its ' + v.feedItemCount + ' item(s) had a usable publication date, so the 24-hour window could not be applied. This is NOT a quiet day.');
} else {
  verdict = 'SOURCE DOWN';
  let msg = '';
  if (v.status === 'invalid') msg = 'invalid RSS/XML: ' + String(v.reason || '');
  else {
    const e = v.error;
    if (typeof e === 'string') msg = e;
    else if (e && typeof e === 'object') msg = String(e.message || e.description || '');
    if (!msg) msg = String(v.message || '');
  }
  let cat = 'unexpected retrieval error';
  if (v.status === 'invalid') cat = 'response was not valid RSS/XML';
  else if (/time(d)?[ -]?out|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg)) cat = 'request timed out';
  else if (/ECONNREFUSED|ENOTFOUND|ECONNRESET|EAI_AGAIN|socket hang up|getaddrinfo/i.test(msg)) cat = 'connection failed';
  else if (/\b([45]\d\d)\b/.test(msg)) cat = 'HTTP error status ' + msg.match(/\b([45]\d\d)\b/)[1];
  else if (/xml|parse|unexpected|non-whitespace|unclosed|attribute/i.test(msg)) cat = 'response was not valid RSS/XML';
  summary = 'Dark Reading feed unavailable or invalid (' + cat + ')';
  lines.push('SOURCE DOWN: the Dark Reading RSS feed could not be retrieved or validated (' + cat + '). No briefing was generated. This is not a quiet day; please check the source.');
}
return [{ json: { verdict: verdict, summary: summary, body: lines.join(LF), sentUrls: [] } }];

const LF = String.fromCharCode(10);
const j = $input.first().json || {};
const execId = String($execution.id || 'n/a');
function istNow() {
  const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
  const g = function (t) { return p.find(function (x) { return x.type === t; }).value; };
  return g('year') + '-' + g('month') + '-' + g('day') + ' ' + g('hour') + ':' + g('minute') + ' IST';
}
const PATTERNS = [
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(-----END [A-Z ]*PRIVATE KEY-----|$)/g, '[REDACTED_KEY]'],
  [/\b\d{6,12}:[A-Za-z0-9_-]{30,}/g, '[REDACTED_TOKEN]'],
  [/\bbearer\s+[A-Za-z0-9._~+\/=-]{8,}/gi, 'Bearer [REDACTED]'],
  [/\bsk-[A-Za-z0-9_-]{16,}/g, '[REDACTED_KEY]'],
  [/\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g, '[REDACTED_KEY]'],
  [/\b(?:ghp|gho|ghs|ghu|github_pat)_[A-Za-z0-9_]{20,}/g, '[REDACTED_TOKEN]'],
  [/\bxox[abprs]-[A-Za-z0-9-]{10,}/g, '[REDACTED_TOKEN]'],
  [/\bAIza[0-9A-Za-z_-]{30,}/g, '[REDACTED_KEY]'],
  [/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g, '[REDACTED_JWT]'],
  [/([?&](?:api[_-]?key|apikey|access_token|token|secret|sig|signature|key)=)[^&\s]+/gi, '$1[REDACTED]'],
  [/\b(api[_-]?key|apikey|access[_-]?token|auth[_-]?token|client[_-]?secret|secret|password|passwd|token|authorization)(\s*[:=]\s*)["']?[^\s"',;&]{6,}/gi, '$1$2[REDACTED]'],
  [/\b[a-f0-9]{40,}\b/gi, '[REDACTED_HEX]'],
  [/^\s+at .*$/gm, '']
];
function redact(s) {
  let t = String(s === undefined || s === null ? '' : s);
  PATTERNS.forEach(function (pr) { t = t.replace(pr[0], pr[1]); });
  return t;
}
function esc(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const verdict = redact(j.verdict || 'ERROR').replace(/\s+/g, ' ').trim();
const summary = redact(j.summary || 'No summary').replace(/\s+/g, ' ').trim().slice(0, 140);
const header = '\uD83D\uDFE3 NGP-015 | exec #' + execId + ' | ' + istNow() + ' | ' + verdict + ' | ' + summary;
let text = header + LF + LF + redact(j.body || '');
if (text.length > 4000) text = text.slice(0, 3990) + LF + '[truncated]';
return [{ json: { text: esc(text), verdict: verdict, sentUrls: j.sentUrls || [] } }];

const r = $('Redact & Add Header').first().json;
const urls = r.sentUrls || [];
if ($execution.mode === 'manual') {
  return [{ json: { recorded: 0, skipped: 'manual run' } }];
}
const sd = $getWorkflowStaticData('global');
const seen = sd.seenUrls || {};
const now = Date.now();
urls.forEach(function (u) { seen[u] = now; });
sd.seenUrls = seen;
return [{ json: { recorded: urls.length } }];

const LF = String.fromCharCode(10);
const now = Date.now();
const cutoff = now - 24 * 3600 * 1000;
const j = $input.first().json || {};
let ch = j.rss && j.rss.channel;
if (Array.isArray(ch)) ch = ch[0];
if (!ch || typeof ch !== 'object') {
  return [{ json: { status: 'invalid', reason: 'Response is not a valid RSS feed (no channel element)', articles: [], articleCount: 0, undatedCount: 0, alreadySentCount: 0 } }];
}
let raw = ch.item;
if (raw === undefined || raw === null) raw = [];
if (!Array.isArray(raw)) raw = [raw];

function txt(v) {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number') return String(v);
  if (typeof v === 'object') {
    if (typeof v._ === 'string') return v._;
    if (typeof v['#text'] === 'string') return v['#text'];
  }
  return '';
}
function strip(s) {
  return String(s).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
}
function canon(u) {
  const m = String(u).trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)/i);
  if (!m) return '';
  return m[1].toLowerCase() + '://' + m[2].toLowerCase() + m[3].replace(/\/+$/, '');
}
function istStr(ms) {
  const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms));
  const g = function (t) { return p.find(function (x) { return x.type === t; }).value; };
  return g('year') + '-' + g('month') + '-' + g('day') + ' ' + g('hour') + ':' + g('minute') + ' IST';
}

const sd = $getWorkflowStaticData('global');
if (sd.seenVersion !== 3) { sd.seenUrls = {}; sd.seenVersion = 3; }
const seen = sd.seenUrls || {};
Object.keys(seen).forEach(function (k) { if (now - seen[k] > 72 * 3600 * 1000) delete seen[k]; });
sd.seenUrls = seen;

const undated = [];
const noLink = [];
const byUrl = new Map();
let datedCount = 0;
let alreadySent = 0;

raw.forEach(function (it) {
  const title = strip(txt(it.title)) || '(untitled)';
  const link = txt(it.link).trim() || txt(it.guid).trim();
  const c = canon(link);
  if (!c) { noLink.push(title); return; }
  const pubRaw = txt(it.pubDate) || txt(it['dc:date']) || txt(it.isoDate);
  const t = pubRaw ? Date.parse(pubRaw) : NaN;
  if (!pubRaw || isNaN(t) || t > now + 3600 * 1000) { undated.push(title); return; }
  datedCount++;
  if (t < cutoff) return;
  if (seen[c]) { alreadySent++; return; }
  if (byUrl.has(c)) return;
  byUrl.set(c, {
    title: title,
    url: c,
    publishedISO: new Date(t).toISOString(),
    publishedIST: istStr(t),
    ts: t,
    summary: strip(txt(it.description) || txt(it['content:encoded'])).slice(0, 600)
  });
});

const articles = Array.from(byUrl.values()).sort(function (a, b) { return b.ts - a.ts; }).slice(0, 15);
let status = 'ok';
let reason = '';
if (raw.length > 0 && datedCount === 0) {
  status = 'dataquality';
  reason = 'Feed items have missing or invalid publication dates; the 24-hour window cannot be applied reliably';
} else if (articles.length === 0) {
  status = 'quiet';
}
return [{ json: {
  status: status,
  reason: reason,
  feedItemCount: raw.length,
  articleCount: articles.length,
  undatedCount: undated.length,
  noLinkCount: noLink.length,
  alreadySentCount: alreadySent,
  articles: articles,
  articlesJson: JSON.stringify(articles.map(function (a, i) { return { n: i + 1, title: a.title, url: a.url, published: a.publishedIST, summary: a.summary }; }))
} }];

const LF = String.fromCharCode(10);
const v = $('Validate & Filter Articles').first().json;
const out = String(($input.first().json || {}).output || '').trim();
if (!out) {
  const fl = ['The AI summarization step failed or returned nothing after a limited retry. Raw headlines are listed instead so nothing is missed:', ''];
  v.articles.slice(0, 8).forEach(function (a, i) { fl.push((i + 1) + '. ' + a.title + ' - ' + a.url); });
  return [{ json: { verdict: 'ERROR', summary: 'AI briefing generation failed; raw headlines attached', body: fl.join(LF), sentUrls: [] } }];
}
let verdict = 'INFO';
let body = out;
const m = out.match(/^\s*SEVERITY:\s*(INFO|LOW|MEDIUM|HIGH|CRITICAL)\s*/i);
if (m) {
  verdict = m[1].toUpperCase();
  body = out.slice(m[0].length).trim();
}
const EXPLOIT = /exploited in the wild|actively exploited|active exploitation|actively being exploited|being exploited|exploited by|exploitation in the wild|in the wild|actively used in attacks|actively attacking|under attack/i;
const SEV = ['INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
const bl = body.split(LF);
const starts = [];
bl.forEach(function (ln, i) { if (/^\[(INFO|LOW|MEDIUM|HIGH|CRITICAL)\]/.test(ln)) starts.push(i); });
let maxIdx = -1;
starts.forEach(function (s, k) {
  const e = k + 1 < starts.length ? starts[k + 1] : bl.length;
  let tag = bl[s].match(/^\[(INFO|LOW|MEDIUM|HIGH|CRITICAL)\]/)[1];
  if (tag === 'HIGH' || tag === 'CRITICAL') {
    let art = null;
    for (let i = s; i < e; i++) {
      v.articles.forEach(function (a) { if (bl[i].indexOf(a.url) !== -1) art = a; });
    }
    const src = art ? (art.title + ' ' + art.summary) : '';
    if (!EXPLOIT.test(src)) {
      bl[s] = bl[s].replace('[' + tag + ']', '[MEDIUM]');
      for (let i = s; i < e; i++) {
        if (/^Severity reason:/.test(bl[i])) bl[i] = bl[i] + ' [Automatically capped at MEDIUM: the available RSS teaser text does not explicitly state exploitation in the wild.]';
      }
      tag = 'MEDIUM';
    }
  }
  maxIdx = Math.max(maxIdx, SEV.indexOf(tag));
});
if (maxIdx >= 0) verdict = SEV[maxIdx];
body = bl.join(LF);
const used = v.articles.filter(function (a) { return body.indexOf(a.url) !== -1; });
const lines = [body, ''];
if (v.undatedCount > 0) {
  lines.push('Data quality: ' + v.undatedCount + ' feed item(s) skipped because of missing or invalid publication dates.');
}
lines.push('');
lines.push('Original links:');
(used.length ? used : v.articles).forEach(function (a, i) { lines.push((i + 1) + '. ' + a.title + ' - ' + a.url + ' (' + a.publishedIST + ')'); });
return [{ json: {
  verdict: verdict,
  summary: 'Threat briefing from ' + v.articleCount + ' Dark Reading article(s) in the last 24h',
  body: lines.join(LF),
  sentUrls: v.articles.map(function (a) { return a.url; })
} }];
